/* ===== Phase IV · Offline support =====
 * public/sw.js (generated by scripts/build_web.py) precaches the core files under a cache named after a hash of
 * every published file, so a new build gets a new cache and old caches are deleted on activation. Requests are
 * network-first with a cache fallback: online visitors always get the current files; offline visitors get the
 * last copy cached. The predictor stack, atlas grids, Earth sub-cell data, Phase II series and the registry are
 * SHA-256-verified on load, and the atlas / registry / Phase II context must name the same stack, so a stale or
 * corrupted cached copy of those files is refused (with a message) rather than used. Needs the network: web fonts (system fonts are used
 * offline), external source links, and files never opened online before (e.g. the Phase II series). */
const A4O = { sw: null, status: null, est: null, err: null };
function a4SwMsg(msg) {
  return new Promise(res => {
    const c = navigator.serviceWorker && navigator.serviceWorker.controller; if (!c) return res(null);
    const ch = new MessageChannel(); ch.port1.onmessage = e => res(e.data); c.postMessage(msg, [ch.port2]); setTimeout(() => res(null), 3000);
  });
}
async function a4OfflineRefresh() {
  try { A4O.status = await a4SwMsg({ type: "status" }); } catch (e) { A4O.err = e.message; }
  try { if (navigator.storage && navigator.storage.estimate) A4O.est = await navigator.storage.estimate(); } catch (e) { }
  if (S.tab === "atlas" && A3.view === "readiness") atRender();
}
function a4OfflinePanel() {
  const sup = "serviceWorker" in navigator, st = A4O.status;
  const est = A4O.est ? `${(A4O.est.usage / 1048576).toFixed(1)} MB used of ~${(A4O.est.quota / 1048576).toFixed(0)} MB available to this site` : "storage estimate unavailable";
  return `<div class="sec" id="offline"><div class="lbl">Offline use</div>
    ${!sup ? `<p class="note">This browser does not support service workers; the app works online only.</p>` :
      !A4O.sw ? `<p class="note">Offline support is ${location.protocol === "file:" ? "unavailable from a file:// page" : "not active yet (it registers after the first full load)"}.</p>` :
      `<p class="note">Service worker ${st ? `active · cache <span class="mono">${esc(st.cache)}</span> · ${st.coreCached}/${st.core} core files cached${st.coreCached < st.core ? " (offline start needs every core file; open the app online once more)" : " — the app can start offline"} · ${st.entries} files in total` : "registered; status pending"} · ${esc(est)}.</p>`}
    <p class="meta small">Works offline once cached: Explore, Compare, Scenarios, Discover, Data, Method, the Atlas and every Phase IV module. Needs the network: web fonts (system fonts are used offline), external source links, and any file not yet opened online (the Phase II time series loads on first use). The predictor stack, atlas grids, sub-cell data, Phase II series and registry are SHA-256-verified when loaded (app.json, targets and labels are not individually hashed); a stale or damaged copy of a verified file is refused with a message — clear the cache below and reload online.</p>
    <div class="row"><button class="btn-sm" data-a4="swrefresh" ${A4O.sw ? "" : "disabled"}>Refresh status</button><button class="btn-sm" data-a4="swclear" ${A4O.sw ? "" : "disabled"}>Clear offline cache</button></div>
    ${A4O.err ? `<p class="small st-m">${esc(A4O.err)}</p>` : ""}</div>`;
}
Object.assign(A4_ACTIONS, {
  swrefresh() { a4OfflineRefresh(); },
  async swclear() { const r = await a4SwMsg({ type: "clear" }); A4O.status = null; A4O.err = r && r.cleared != null ? `Cleared ${r.cleared} cache(s). Reload while online to re-cache.` : "The service worker did not answer."; atRender(); },
});
(function a4Register() {
  if (!("serviceWorker" in navigator) || location.protocol === "file:") return;
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("sw.js").then(reg => { A4O.sw = reg; setTimeout(a4OfflineRefresh, 1500); })
      .catch(e => { A4O.err = "Service worker registration failed: " + e.message; });
  });
})();
